import {installAutoReports} from './auto-report-ui.mjs';
import {makeCSVReport,parseSensorCSV} from './csv-analysis.mjs';
import {csvAssessment,csvResultHTML} from './csv-report-ui.mjs';
import { analyzeTrial, analyzeFoot, SOURCES, FIELDS, LIMITATIONS, VERSION, STUDY_VALUES, assessChange } from './research-analysis.mjs';
import { mean, sd } from './analysis.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>Number.isFinite(v)?v.toFixed(d):'—',foot=s=>s==='L'?'왼발':'오른발';
let participant=$('participant').value||'P1',trials=[],saved=[],selected=null,result=null,live=null,uploaded=null,config=null,generation=0,lastLive=0,aiPending=null;
const section=document.createElement('section');section.id='research-section';section.className='research-section';
section.innerHTML=`<div class="section-heading"><div><p class="eyebrow">CSV GAIT ANALYSIS</p><h2>CSV 기반 AI 보행 분석</h2></div><span class="badge">펌웨어 유지 · 연구 분석</span></div>
<div class="research-note" role="status" aria-live="polite"><strong id="gait-assessment-status">보행 패턴을 확인할 기록을 기다리고 있습니다</strong><p id="gait-assessment-action">정제한 CSV의 신호 변화·좌우 차이·측정 품질을 AI가 설명합니다.</p><span class="caption">진단을 대신하지 않는 보행 기록 안내입니다.</span></div>
<div class="panel research-controls"><label>분석할 기록<select id="research-trial"><option value="live">실시간 · 최근 60초</option></select></label><button id="research-refresh" class="secondary">목록 새로고침</button><label>보행 경로<select id="research-path"><option value="unknown">미기록 / 회전·정지 포함</option><option value="straight">직선 보행</option></select></label><label>실측 보행 속도 (m/s)<input id="research-speed" type="number" min="0.1" max="4" step="0.01" placeholder="거리 ÷ 시간, 선택"></label><label class="check"><input id="research-matched" type="checkbox"> 기준선과 속도·장착·복약 조건이 같음을 확인</label><button id="research-run">CSV 정제·그래프 보기</button></div>
<p class="caption">주기 10회·기준선 3회·최소 20초 조건 없이 CSV를 분석합니다. 짧거나 결측이 많은 기록도 AI가 한계를 설명합니다. 속도·보행 경로는 알고 있을 때만 입력하세요.</p><div class="panel spaced"><h3>기존 원시 CSV 불러오기</h3><label>CSV의 발 구분<select id="csv-side"><option value="">CSV의 side 열 사용</option><option value="L">side 열이 없으면 왼발</option><option value="R">side 열이 없으면 오른발</option></select></label><label>원시·필터 CSV 파일<input id="csv-upload" type="file" accept=".csv,text/csv"></label><p class="caption">파일을 선택하면 기기에서 정제·미리보기합니다. AI 분석 버튼을 누르기 전에는 OpenAI로 전송하지 않습니다. 정제된 숫자 열만 전송하며 이름·참여자 코드·기기 ID·절대 시각은 제외합니다.</p></div>
<p id="research-notice" class="notice" role="status" aria-live="polite">보정된 센서 또는 저장된 Trial을 선택하세요.</p>
<div id="research-result"></div>
<div class="panel research-ai"><h3>AI 상세 분석</h3><p class="caption">정제된 CSV 센서값·경과 시간·발 구분과 전체 통계·질문을 OpenAI GPT-6.1 Terra로 전송합니다. 긴 기록은 전체 통계와 최대 약 3,000개 대표 행을 전달하며 전송 행 수를 표시합니다. 참여자 코드·기기 ID·연락처·복약 목록은 자동 전송하지 않습니다.</p><div class="form-grid"><label class="full">AI 이용 코드<input id="ai-access" type="password" autocomplete="off" maxlength="200" placeholder="관리자가 발급한 이용 코드 · API 키 입력 금지"></label><label class="full">분석 요청<textarea id="ai-question" rows="2" maxlength="1000">CSV의 앞뒤 FSR과 자세각 변화를 분석하고, 누락·센서 감도·장착 차이와 좌우 보행 차이를 구분해 주세요. 재측정과 전문 의료진 상담이 필요한 조건을 설명해 주세요.</textarea></label><label class="check full"><input id="ai-consent" type="checkbox"> 정제 CSV 센서값·통계·질문의 OpenAI 전송에 동의합니다. 자동 리포트를 켜면 측정 종료 후에도 적용됩니다. 질문에 이름·연락처를 넣지 않습니다.</label><button id="auto-report-apply" class="secondary full">자동 리포트 설정 적용 / 실패 작업 재시도</button><button id="research-ai" class="full">CSV AI 분석·리포트 저장</button></div><p id="ai-status" role="status" aria-live="polite"></p><div id="research-ai-output"></div></div>
<div class="actions spaced"><button id="research-save" disabled>상세 보고서 저장</button><button id="research-json" class="secondary" disabled>분석 JSON</button><button id="research-csv" class="secondary" disabled>정제 CSV</button><button id="research-html" class="secondary" disabled>그래프 포함 HTML</button><button id="research-print" class="secondary" disabled>인쇄·PDF</button></div>
<details class="panel spaced"><summary>판단 예시 · 실제 측정 기록과 별도</summary><p class="caption">아래 수치는 팀의 변화 확인 규칙을 설명하는 가상 사례입니다. 파킨슨병 확률·낙상 위험의 임상 기준이 아닙니다.</p><table><thead><tr><th>가상 사례</th><th>기준선 → 현재</th><th>판단 예시</th></tr></thead><tbody><tr><td>조건이 같은 안정적인 기록</td><td>주기 CV 4 → 4.2%, 접촉 CV 5 → 5.3%</td><td>증가율 20% 미만 · 설정 기준 내 변화</td></tr><tr><td>같은 조건에서 반복된 변화</td><td>주기 CV 4 → 5.2%, 접촉 CV 5 → 7%</td><td>보행 패턴 이상 징후 · 재측정 후 지속되면 전문 의료진 평가 권고</td></tr><tr><td>짧은 기록 / 패킷 공백</td><td>8초 / 유효 주기 4회</td><td>측정 품질 확인 · 변화 판단 보류</td></tr></tbody></table></details>
<details class="panel spaced"><summary>논문 근거 · 적용 범위 · 산출하지 않는 항목</summary>${sourcesHTML()}<ul>${LIMITATIONS.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="caption">알고리즘 ${VERSION} · 접촉 on/off 0.15/0.08, 최소 접촉 0.12초, 기록 20초·주기 10회, CV 증가 20% 등은 팀의 연구 설정입니다. 논문의 진단 임계값이 아닙니다. WearGait의 0.1–2.0초 주기 제외를 응용했으며 데이터 손실은 100 Hz의 7프레임 규칙을 그대로 가져오지 않습니다.</p></details>`;
document.querySelector('[data-view-panel="analysis"]').prepend(section);
const list=document.createElement('section');list.innerHTML='<div class="section-heading"><h2>논문 기반 상세 보고서</h2><button id="open-research" class="secondary">보행 분석에서 생성</button></div><div id="research-reports" class="record-list"></div>';
document.querySelector('[data-view-panel="reports"]').append(list);
$('open-research').onclick=()=>{window.earlybirdNavigate('analysis');section.scrollIntoView({behavior:'smooth'});};
function sourcesHTML(){return '<ul class="research-sources">'+SOURCES.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)}</a><p>${esc(s.method)}</p></li>`).join('')+'</ul><h4>연구 집단 참고값 · 개인의 진단 기준 아님</h4><div class="table-wrap"><table><thead><tr><th>연구 / 지표</th><th>대조군 평균 ± SD</th><th>PD 집단 평균 ± SD</th><th>p</th></tr></thead><tbody>'+STUDY_VALUES.map(v=>`<tr><td>${esc(v.source)}<br>${esc(v.metric)}</td><td>${v.control}</td><td>${v.pd}</td><td>${v.p}</td></tr>`).join('')+'</tbody></table></div><p class="caption">두 연구의 센서·보행 속도·복약 조건이 다릅니다. 현재 장치의 측정값을 이 집단 평균에 대입해 정상/파킨슨병을 분류하거나 확률을 계산하지 않습니다. p값은 집단 차이의 검정 결과이며 개인의 질병 확률이 아닙니다.</p>';}
function note(s,error=false){$('research-notice').textContent=s;$('research-notice').classList.toggle('error',error);}
async function api(path,payload){const r=await fetch(path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});let d;try{d=await r.json();}catch{throw Error('서버 응답을 확인할 수 없습니다. Vercel 배포 주소에서 다시 시도하세요.');}if(!r.ok)throw Error(d.error||'요청 실패');return d;}
function protocol(){const speed=$('research-speed').value;return{straight:$('research-path').value==='straight',speed_mps:speed?Number(speed):null,matched:$('research-matched').checked};}
function invalidate(){$('gait-assessment-status').textContent='보행 패턴을 확인할 기록을 기다리고 있습니다';$('gait-assessment-action').textContent='정제한 CSV의 신호 변화·좌우 차이·측정 품질을 AI가 설명합니다.';result=null;selected=null;generation++;$('research-result').replaceChildren();$('research-ai-output').replaceChildren();$('ai-status').textContent='';for(const id of ['save','json','csv','html','print'])$('research-'+id).disabled=true;}
async function refresh(){const who=participant,v=++generation;try{const [state,p,c]=await Promise.all([api('/api/state?participant='+encodeURIComponent(who)),api('/api/platform?participant='+encodeURIComponent(who)),api('/api/config')]);if(v!==generation||who!==participant)return;config=c;trials=state.trials;saved=p.researchs||[];const old=$('research-trial').value;$('research-trial').replaceChildren();for(const [value,text]of [['live','실시간 · 최근 60초'],...(uploaded?[['csv-upload','불러온 CSV']]:[]),...trials.map(t=>[t.id,`${new Date(t.created_at).toLocaleString('ko-KR')} · ${t.condition} / ${t.trial}`])]){const o=document.createElement('option');o.value=value;o.textContent=text;$('research-trial').append(o);}if([...$('research-trial').options].some(o=>o.value===old))$('research-trial').value=old;renderSaved();autoReports.restore(who,saved);}catch(e){if(v===generation)note(e.message,true);}}
function plot(series,{xlabel='보행 주기 (%)',ylabel='FSR 상대값',label='주기 파형'}={}) {
  const active=series.filter(s=>s.values?.length&&s.values.every(Number.isFinite));if(!active.length)return '<p class="empty">유효한 주기가 부족해 그래프를 표시하지 않습니다.</p>';
  const vals=active.flatMap(s=>s.values.flatMap((v,i)=>[v-(s.sd?.[i]||0),v+(s.sd?.[i]||0)]));let lo=Math.min(0,...vals),hi=Math.max(...vals);if(hi-lo<1e-9)hi=lo+1;
  const X=(i,n)=>60+680*i/Math.max(1,n-1),Y=v=>205-160*(v-lo)/(hi-lo),line=values=>values.map((v,i)=>(i?'L':'M')+X(i,values.length).toFixed(2)+','+Y(v).toFixed(2)).join(' ');
  let html=`<svg viewBox="0 0 800 255" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>`;
  for(let i=0;i<5;i++){const y=45+i*40;html+=`<path d="M60 ${y}H740" stroke="#e2eaed"/><text x="52" y="${y+4}" text-anchor="end">${num(hi-(hi-lo)*i/4)}</text>`;}
  for(const s of active){if(s.sd){const upper=s.values.map((v,i)=>[X(i,s.values.length),Y(v+s.sd[i])]),lower=s.values.map((v,i)=>[X(i,s.values.length),Y(v-s.sd[i])]).reverse();html+=`<path d="M${[...upper,...lower].map(p=>p.map(v=>v.toFixed(2)).join(',')).join('L')}Z" fill="${s.color}" opacity=".12"/>`;}html+=`<path d="${line(s.values)}" stroke="${s.color}" stroke-width="2" fill="none"${s.dashed?' stroke-dasharray="7 4"':''}/>`;}
  html+=`<text x="60" y="225">${esc(active[0].xStart??'0')}</text><text x="740" y="225" text-anchor="end">${esc(active[0].xEnd??'100')}</text><text x="400" y="247" text-anchor="middle">${esc(xlabel)}</text><text x="60" y="20">${esc(ylabel)}</text></svg><p class="caption">${active.map(s=>`<span style="color:${s.color}">${esc(s.name)}</span>`).join(' · ')}</p>`;return html;
}
function currentAssessment(r){if(r.input_mode==='csv')return csvAssessment(r);return assessChange(r.sides,r.reference,r.protocol?.straight===true&&Number.isFinite(r.protocol.speed_mps)&&r.protocol.speed_mps>0&&r.protocol.matched===true);}
function resultHTML(r){if(r.input_mode==='csv')return csvResultHTML(r);const assessment=currentAssessment(r),sides=Object.keys(r.sides),rows=Object.entries(FIELDS).map(([k,[name,unit]])=>`<tr><td>${name} (${unit})</td>${['L','R'].map(s=>`<td>${num(r.sides[s]?.metrics[k])}</td>`).join('')}<td>${num(r.asymmetry[k])}</td></tr>`).join('');
  const curves=key=>plot(sides.map(s=>({values:r.sides[s].ensemble[key].mean,sd:r.sides[s].ensemble[key].sd,color:s==='L'?'#247c79':'#5b54a6',dashed:s==='R',name:`${foot(s)} · ${r.sides[s].ensemble[key].n}주기`})),{ylabel:key==='pitch_relative'?'피치 (°)':'FSR 상대값',label:key+' 주기 평균 ± SD'});
  return `<article class="research-document"><div class="panel"><p class="eyebrow">GAIT RESEARCH REPORT</p><h3>${r.trial_id?'저장 Trial 전체 구간':'실시간 최근 구간'} · ${esc(r.condition)}</h3><p class="caption">${esc(new Date(r.created_at).toLocaleString('ko-KR'))} · ${esc(r.schema)} · 직선 보행 ${r.protocol.straight?'입력됨':'미확인'} · 속도 ${num(r.protocol.speed_mps)} m/s (직접 입력)</p><div class="research-note"><h3>${esc(assessment.headline)}</h3><p>${esc(assessment.action)}</p></div><p class="caption">${esc(assessment.rule)}</p><div class="table-wrap"><table><thead><tr><th>품질</th><th>왼발</th><th>오른발</th></tr></thead><tbody>${[['duration','구간 길이 (초)'],['cycles','유효 주기 수'],['effective_hz','실효 샘플링 (Hz)'],['missing_fraction','누락 비율 (0–1)'],['max_gap_ms','최대 ESP 시각 간격 (ms)'],['rejected_cycles','제외 주기 수']].map(([k,n])=>`<tr><td>${n}</td>${['L','R'].map(s=>`<td>${num(r.sides[s]?.quality[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${sides.map(s=>`<p class="caption">${foot(s)}: ${r.sides[s].quality.usable?'연구 품질 규칙 충족':esc(r.sides[s].quality.issues.join(' · '))}</p>`).join('')}</div>
  <div class="panel spaced"><h3>시간·접촉·자세 지표</h3><div class="table-wrap"><table><thead><tr><th>지표</th><th>왼발</th><th>오른발</th><th>좌우 차이 (%)</th></tr></thead><tbody>${rows}</tbody></table></div><p class="caption">CV = 주기 간 표본 SD / 평균 ×100. 좌우 차이 = 200×|L−R|/(|L|+|R|). 공통 수신 구간과 양쪽 품질 기준이 충족될 때만 비교합니다. 환산 보행률 = 120 / 같은 발 주기이며 두 발의 실제 걸음 검출 수가 아닙니다.</p></div>
  <div class="research-chart-grid"><div class="panel spaced"><h3>앞 FSR · 주기 평균 ± SD</h3>${curves('front_norm')}</div><div class="panel spaced"><h3>뒤 FSR · 주기 평균 ± SD</h3>${curves('rear_norm')}</div><div class="panel spaced"><h3>신발 피치 · 주기 평균 ± SD</h3>${curves('pitch_relative')}</div><div class="panel spaced"><h3>보행 주기별 시간</h3>${plot(sides.map(s=>({values:r.sides[s].cycles.map(c=>c.stride),color:s==='L'?'#247c79':'#5b54a6',name:foot(s),xStart:1,xEnd:r.sides[s].cycles.length})),{xlabel:'발별 주기 순서 (좌우 동기화 아님)',ylabel:'주기 (초)',label:'주기별 시간 변화'})}</div></div>
  <div class="panel spaced"><h3>FSR 주파수 분포 · 탐색용</h3>${plot(sides.filter(s=>r.sides[s].spectrum.available).map(s=>({values:r.sides[s].spectrum.points.map(p=>p.y),color:s==='L'?'#247c79':'#5b54a6',name:foot(s)+' 지배 주파수 '+num(r.sides[s].spectrum.dominant_hz)+' Hz',xStart:num(r.sides[s].spectrum.points[0]?.x),xEnd:num(r.sides[s].spectrum.points.at(-1)?.x)})),{xlabel:'주파수 (Hz)',ylabel:'PSD (상대값²/Hz)',label:'FSR 합산 신호의 탐색용 주파수 분포'})}<p class="caption">20 Hz 리샘플 · Hann 128점 · Welch 50% 중첩 · 0.5–3 Hz · 주파수 간격 0.15625 Hz. 가속도 PSD가 아니므로 Weiss 논문의 평균·폭·기울기와 수치 비교하지 않습니다.</p>${sides.filter(s=>!r.sides[s].spectrum.available).map(s=>`<p class="caption">${foot(s)}: ${esc(r.sides[s].spectrum.reason)}</p>`).join('')}</div>
  <div class="panel spaced"><h3>개인 기준선 대비 변화</h3>${assessment.changes.length?`<table><thead><tr><th>발 / 지표</th><th>기준선 (Trial 수)</th><th>현재</th><th>증가율</th></tr></thead><tbody>${assessment.changes.map(c=>`<tr><td>${foot(c.side)} / ${FIELDS[c.key][0]}</td><td>${num(c.baseline)} (${c.n})</td><td>${num(c.value)}</td><td>${num(c.percent)}%${c.flag?' · 표시 기준 이상':''}</td></tr>`).join('')}</tbody></table>`:'<p>동일 보정·설정의 유효 Normal 기준선이 발별 3회 이상 필요합니다. 서 있는 기록은 기준선이 될 수 없습니다.</p>'}<p class="caption">측정 조건이 다르면 증가율을 질병 변화로 해석할 수 없습니다. 기준선 데이터의 보행 속도가 자동 검증되는 것은 아닙니다.</p></div></article>`;
}
function aiHTML(ai){if(!ai)return '';const c=ai.csv_context;const coverage=c?'<p class="caption">전체 정제 '+c.total_rows+'행 / AI 전송 '+c.transmitted_rows+'행 · '+esc(c.method)+'</p>':'';return '<div class="panel spaced"><h3>AI 설명 · '+esc(ai.model)+'</h3>'+coverage+'<p class="caption">'+esc(ai.created_at)+' · 계산 결과를 설명하는 언어 모델 · 임상 예측 모델 아님</p>'+Object.entries({summary:'요약',observations:'관찰',quality:'측정 품질',limitations:'해석 한계',next_steps:'다음 확인 사항'}).map(([k,title])=>'<h4>'+title+'</h4><p class="ai-text">'+esc(ai.analysis[k])+'</p>').join('')+'<p class="caption">이 설명은 보행 기록을 이해하기 위한 자료입니다. 질병 여부와 치료 필요성은 전문 의료진이 판단합니다.</p>'+sourcesHTML()+'</div>';}
function documentHTML(r){if(r.input_mode==='csv')return resultHTML(r)+aiHTML(r.ai);return resultHTML(r)+aiHTML(r.ai)+'<div class="panel spaced"><h3>근거와 해석 범위</h3>'+sourcesHTML()+'<ul>'+LIMITATIONS.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>';}
function renderResult(){if(!result)return;const assessment=currentAssessment(result);if($('gait-assessment-status').textContent!==assessment.headline)$('gait-assessment-status').textContent=assessment.headline;if($('gait-assessment-action').textContent!==assessment.action)$('gait-assessment-action').textContent=assessment.action;$('research-result').innerHTML=resultHTML(result);$('research-ai-output').innerHTML=aiHTML(result.ai);for(const id of ['json','csv','html','print'])$('research-'+id).disabled=false;$('research-save').disabled=!result.trial_id&&result.source_type!=='csv_upload';}
async function baseline(trial,observedTrials=trials){const reference={};for(const s of ['L','R']){const candidates=observedTrials.filter(t=>t.id!==trial.id&&t.baseline&&t.condition==='Normal'&&t.calibration_ids[s]===trial.calibration_ids?.[s]&&JSON.stringify(t.config_snapshot)===JSON.stringify(trial.config_snapshot));const observations=[];for(const t of candidates.slice(0,20)){const full=await api('/api/trials/'+encodeURIComponent(t.id)),a=analyzeFoot(full.samples.filter(r=>r.side===s),t.config_snapshot||config);if(a.quality.usable)observations.push(a.metrics);}reference[s]=Object.fromEntries(Object.keys(FIELDS).map(k=>{const values=observations.map(m=>m[k]).filter(Number.isFinite);return[k,{n:values.length,mean:mean(values),sd:sd(values)}];}));}return reference;}
async function run(){invalidate();const who=participant,v=generation,id=$('research-trial').value;try{if(!$('research-speed').checkValidity())throw Error('속도는 0.1–4 m/s로 입력하거나 비워 두세요.');const trial=id==='csv-upload'?uploaded:id==='live'?live:await api('/api/trials/'+encodeURIComponent(id));if(!trial?.samples?.length)throw Error('분석할 센서 데이터가 없습니다. 저장된 기록 또는 원시 CSV를 선택하세요.');if(who!==participant||v!==generation)return;selected=trial;result=makeCSVReport(trial,protocol());renderResult();note('CSV 정제·통계 분석 완료 · '+result.csv.summary.cleaning.kept_rows+'행 · 주기 수 조건 없이 AI 분석할 수 있습니다.');}catch(e){if(v===generation)note(e.message,true);}}

$('csv-upload').onchange=async()=>{const file=$('csv-upload').files[0];if(!file)return;invalidate();uploaded=null;if(![...$('research-trial').options].some(o=>o.value==='csv-upload'))$('research-trial').append(new Option('불러온 CSV','csv-upload'));$('research-trial').value='csv-upload';const who=participant,v=generation;try{if(file.size>8000000)throw Error('CSV 파일은 8MB 이하로 선택하세요.');const clean=parseSensorCSV(await file.text(),$('csv-side').value||undefined);if(who!==participant||v!==generation)return;uploaded={source_type:'csv_upload',samples:clean.rows,cleaned:clean,condition:'unknown'};if(![...$('research-trial').options].some(o=>o.value==='csv-upload'))$('research-trial').append(new Option('불러온 CSV','csv-upload'));$('research-trial').value='csv-upload';await run();}catch(e){if(who===participant&&v===generation){invalidate();note('CSV 불러오기 실패: '+e.message,true);}}};
$('csv-side').onchange=()=>{if($('csv-upload').files.length)void $('csv-upload').onchange();};
$('research-run').onclick=run;$('research-refresh').onclick=refresh;
for(const id of ['research-trial','research-path','research-speed','research-matched'])$(id).addEventListener('change',()=>{invalidate();note('선택·측정 조건이 변경되었습니다. 전체 기록 분석을 다시 실행하세요.');});
$('research-save').onclick=async()=>{if(!result||!result.trial_id&&result.source_type!=='csv_upload')return;const report=structuredClone(result),who=participant,v=generation;try{const item=await api('/api/platform/research',{participant_id:who,report});if(participant!==who||v!==generation)return;note('상세 보고서를 저장했습니다. 건강 리포트 메뉴에서 다시 열 수 있습니다.');saved.unshift(item);renderSaved();}catch(e){note('저장 실패: '+e.message+' 분석 JSON으로 백업할 수 있습니다.',true);}};
function download(name,text,type='application/json'){window.earlybirdReportTools.download('ENDEAVOR_'+name,text,type);}
$('research-json').onclick=()=>result&&download('research.json',JSON.stringify(result,null,2));
$('research-csv').onclick=()=>{if(!result)return;if(result.input_mode==='csv')return download('cleaned_sensor.csv','\ufeff'+result.csv.text,'text/csv;charset=utf-8');const rows=[['side','metric','value','unit','AI_percent'],...Object.keys(result.sides).flatMap(s=>Object.entries(FIELDS).map(([k,[,u]])=>[s,k,result.sides[s].metrics[k],u,result.asymmetry[k]]))];download('research.csv','\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');};
$('research-html').onclick=()=>result&&window.earlybirdReportTools.exportHTML('research',documentHTML(result));
$('research-print').onclick=()=>result&&window.earlybirdReportTools.printHTML('논문 기반 보행 상세 보고서',documentHTML(result));
function renderSaved(){const target=$('research-reports');target.replaceChildren();if(!saved.length){target.textContent='저장된 논문 기반 상세 보고서가 없습니다.';return;}for(const item of saved){const box=document.createElement('article');box.className='panel record-card';const body=document.createElement('div');body.textContent=new Date(item.created_at).toLocaleString('ko-KR')+' · '+item.report.condition+' · '+(item.report.automatic?'자동 리포트 · '+(item.report.auto_state==='completed'?'생성 완료':item.report.auto_state==='failed'?'생성 실패 / 재시도 가능':'생성 대기'):(item.report.ai?'AI 설명 포함':'수치·그래프'));const b=document.createElement('button');b.textContent='상세 보고서 열기';b.onclick=()=>{const html=documentHTML(item.report),tools=window.earlybirdReportTools;const action=(text,fn)=>{const n=document.createElement('button');n.textContent=text;n.onclick=fn;return n;};tools.modal('논문 기반 보행 상세 보고서',html,[action('인쇄·PDF',()=>tools.printHTML('논문 기반 보행 상세 보고서',html)),action('HTML 저장',()=>tools.exportHTML('research_'+item.id,html)),action('JSON 저장',()=>download('research_'+item.id+'.json',JSON.stringify(item.report,null,2)))]);};box.append(body,b);target.append(box);}}
function aiPayload(r){if(r.input_mode==='csv')return {input_mode:'csv',csv:r.csv.text,cleaning:r.csv.summary.cleaning};return {schema:VERSION,condition:r.condition,protocol:r.protocol,sides:Object.fromEntries(Object.entries(r.sides).map(([s,a])=>[s,{metrics:a.metrics,quality:a.quality}])),reference:r.reference,overlap:r.overlap,probability:null};}
$('research-ai').onclick=async()=>{const button=$('research-ai');if(!result)await run();if(!result)return;if(!$('ai-consent').checked)return note('정제 CSV·통계·질문의 OpenAI 전송 동의를 선택하세요.',true);const code=$('ai-access').value.trim();if(!code||code.startsWith('sk-'))return note('OpenAI API 키 대신 관리자 AI 이용 코드를 입력하세요.',true);const target=result,v=generation,who=participant;button.disabled=true;aiPending=target;$('ai-status').textContent='AI가 CSV를 분석하고 있습니다. 주기 수와 관계없이 신호와 누락을 검토합니다. 이 창을 열어 두세요.';try{const ai=await api('/api/ai-analyze',{access_code:code,question:$('ai-question').value,report:aiPayload(target)});if(v!==generation||who!==participant||target!==result)return;target.ai=ai;renderResult();const item=await api('/api/platform/research',{participant_id:who,report:structuredClone(target)});if(v!==generation||who!==participant)return;saved=[item,...saved.filter(x=>x.id!==item.id)];renderSaved();$('ai-status').textContent='CSV AI 분석·리포트 저장 완료. 건강 리포트에서 다시 확인할 수 있습니다.';}catch(e){if(v===generation)$('ai-status').textContent=(target.ai?'AI 응답은 화면에 남아 있습니다. 보고서 저장 실패: ':'AI 분석 실패: ')+e.message;}finally{aiPending=null;button.disabled=false;}};
window.addEventListener('earlybird:participant-changing',e=>{participant=e.detail.participant;trials=[];saved=[];live=null;uploaded=null;$('csv-upload').value='';invalidate();$('ai-access').value='';$('ai-consent').checked=false;$('research-reports').replaceChildren();$('research-trial').replaceChildren(new Option('실시간 · 최근 60초','live'));$('research-speed').value='';$('research-path').value='unknown';$('research-matched').checked=false;note('참여자 기록을 불러오는 중입니다.');});
window.addEventListener('earlybird:state',e=>{participant=e.detail.participant;void refresh();});
window.addEventListener('earlybird:samples',e=>{if(e.detail.participant!==participant)return;live=e.detail;if(!live.samples.length){if(result&&!result.ai&&$('research-trial').value==='live')invalidate();return;}if($('research-trial').value!=='live'||!section.checkVisibility()||Date.now()-lastLive<2000||!config)return;lastLive=Date.now();if(result?.ai||aiPending)return;try{result=makeCSVReport(live,protocol());renderResult();}catch(e){note(e.message,true);}});
